import{_ as o,o as a,c as r,a3 as t}from"./chunks/framework.BwzYn71E.js";const k=JSON.parse('{"title":"长周期时钟","description":"","frontmatter":{"translationSource":{"title":"长周期时钟","archivedAt":"2026-10-27","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=l2Igx2VZPkosoaw14MCvfA","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/long-period-clocks"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/long-period-clocks"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/long-period-clocks"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/long-period-clocks"}]]},"headers":[],"relativePath":"zh/long-period-clocks.md","filePath":"zh/page-l2Igx2VZPkosoaw14MCvfA.md"}'),l={name:"zh/long-period-clocks.md"};function i(s,e,n,c,d,p){return a(),r("div",null,[...e[0]||(e[0]=[t('<div class="logistics-content"><span class="logistics-source-anchor" id="长周期时钟" aria-hidden="true"></span><span class="logistics-source-anchor" id="long-period-clock-signals" aria-hidden="true"></span><span class="logistics-source-anchor" id="长周期时钟信号" aria-hidden="true"></span><h1 id="长周期时钟" tabindex="-1">长周期时钟 <a class="header-anchor" href="#长周期时钟" aria-label="Permalink to &quot;长周期时钟&quot;">​</a></h1><blockquote><p>源页面 ID：<code>l2Igx2VZPkosoaw14MCvfA</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=l2Igx2VZPkosoaw14MCvfA" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>相关研究或可参考<br><a href="https://www.bilibili.com/video/BV1PrAazxE7Y" target="_blank" rel="noreferrer">【赤石科技】这才是赤石的终点！都安静，时间由我来分配！</a></p><p><a href="https://github.com/hongshan-academy/discussion/discussions/3" target="_blank" rel="noreferrer">离线补电装置之超低功率发电机</a></p><p><a href="/endfield-skydoc/zh/t-flip-flop">T触发器</a></p><blockquote><p>感觉是不是可以合并到T触发器那边</p></blockquote><blockquote><p>T触发器是方法，这里是需求，这里是方法是否可以满足需求，后续可以添加在T触发器中写一行作为可以实现的需求，但是需求本身并不是实现方法之一的附属，我认为不能合并</p></blockquote><p>整流器\\混箱方法实现</p><p>核心原理是箱子外与箱子内A不同的物品B必须等待箱子内物品A流尽后才可进入，通过对箱子输出限速，可以得到箱子内限速物品A数量*1/限速的时长为周期，使得每个周期后B才进入。具体结构可以参考 君 的满仓震荡方案实现。</p><p>传送带空位法\\临摹法实现</p><p>核心原理是环带混带，环带内物品A之间的空缺可以以低优先汇入插入目标物品B，通过改变传送带上空位所在的位置与间隔，即可调整输出所在的相位。此方法还可以通过对齐相位的串联得到最小公倍数的周期。</p><p>狭义限流器实现</p><p>参考<a href="/endfield-skydoc/zh/flow-theory-for-idealized-logistics-systems">理想系统的流量理论</a>，通过构造1/n式限流实现任意周期。此外，通过将<a href="https://docs.qq.com/aio/DZXhhTUp6WU1Yd3Ba?p=GzlRUGEnEkorT2H6NOunIL&amp;client_hint=0#IXIRHlju0U32xxRj7QSvA6" target="_blank" rel="noreferrer">该结构</a>的输入处的汇流器用协议箱代替，可以实现更加简单方便通用的限流器构造。</p></div>',1)])])}const f=o(l,[["render",i]]);export{k as __pageData,f as default};
